class ClearedValue(object):
    """Wrap a value tagged with !clear in mrjob.conf"""

    def __init__(self, value):
        self.value = value

    def __eq__(self, other):
        if isinstance(other, ClearedValue):
            return self.value == other.value
        else:
            return False

    def __hash__(self):
        return hash(self.value)

    def __repr__(self):
        return '%s(%s)' % (self.__class__.__name__, repr(self.value))

def _fix_opts(self, opts, source=None):
    """Take an options dictionary, and either return a sanitized
    version of it, or raise an exception.

    *source* is either a string describing where the opts came from
    or None.

    This ensures that opt dictionaries are really dictionaries
    and handles deprecated options.
    """
    if source is None:
        source = 'defaults'  # defaults shouldn't trigger warnings

    if not isinstance(opts, dict):
        raise TypeError(
            'options for %s (from %s) must be a dict' %
            (self.alias, source))

    deprecated_aliases = _deprecated_aliases(self.OPT_NAMES)

    results = {}

    for k, v in sorted(opts.items()):
        # rewrite deprecated aliases
        if k in deprecated_aliases:
            if v is None:  # don't care
                continue

            aliased_opt = deprecated_aliases

            log.warning('Deprecated option %s (from %s) has been renamed'
                        ' to %s and will be removed in v0.7.0' % (
                            k, source, aliased_opt))

            if opts.get(aliased_opt) is not None:
                return  # don't overwrite non-aliased opt

            k = aliased_opt

        if k in self.OPT_NAMES:
            if v is None:
                fixed_v = None
            elif isinstance(v, ClearedValue):
                # _fix_opt() doesn't need to know about !clear (see #2102)
                fixed_v = ClearedValue(self._fix_opt(k, v.value, source))
            else:
                fixed_v = self._fix_opt(k, v, source)

            results[k] = fixed_v
        elif v:
            log.warning('Unexpected option %s (from %s)' % (k, source))

    return results

def _conf_object_at_path(conf_path):
    if conf_path is None:
        return None

    with open(conf_path) as f:
        if yaml:
            return _fix_clear_tags(_load_yaml_with_clear_tag(f))
        else:
            try:
                return json.load(f)
            except ValueError as e:
                raise ValueError(
                    'Could not read JSON from %s\n  %s\n\n'
                    'If your conf file is in YAML, you need to'
                    ' `pip install PyYAML` to read it' % (conf_path, str(e)))

def _load_opts_from_mrjob_conf(runner_alias, conf_path, already_loaded):
    """Helper for :py:func:`load_opts_from_mrjob_conf` for recursive use.
    This doesn't expand or default *conf_path*.
    """
    conf = _conf_object_at_path(conf_path)

    if conf is None:
        return [(None, {})]

    # don't load same conf file twice
    real_conf_path = os.path.realpath(conf_path)

    if real_conf_path in already_loaded:
        return []
    else:
        already_loaded.append(real_conf_path)

    # get configs for our runner out of conf file
    try:
        values = conf['runners'][runner_alias] or {}
    except (KeyError, TypeError, ValueError):
        values = {}

    inherited = []
    if conf.get('include', None):
        includes = conf['include']
        if isinstance(includes, string_types):
            includes = [includes]

        # handle includes in reverse order so that include order takes
        # precedence over inheritance
        for include in reversed(includes):
            # make include relative to (real) conf_path (see #1166)
            # expand ~ *before* joining to dir of including file (see #1308)
            include = os.path.join(os.path.dirname(real_conf_path),
                                   expand_path(include))

            inherited = _load_opts_from_mrjob_conf(
                runner_alias, include, already_loaded) + inherited

    return inherited + [(conf_path, values)]
